/* ══ verdict rendering ═════════════════════════════════════════════════════
   The chairman writes ANSWER / NOTES / CONFIDENCE with light markdown inside.
   It is parsed into a small block tree rather than rendered inline, because
   the answer body and the caveats end up in DIFFERENT columns — which a flat
   node list cannot express. */

const SECTION = /^\s*(?:#{1,4}\s*)?(ANSWER|NOTES|CONFIDENCE|VERDICT|AGREEMENTS|DISAGREEMENTS|CAVEATS)\b\s*:?\s*$/i;
const HEADING = /^\s*#{1,6}\s+(.+?)\s*$/;
const BULLET = /^(\s*)[-*•]\s+(.*)$/;
const NUMBERED = /^(\s*)(\d+)[.)]\s+(.*)$/;
/* The rating is split off into a tag only when a separator or a sentence break
 * follows it — "HIGH — the members agreed" or "HIGH. Everyone agreed". The
 * chairman often writes the rating as the SUBJECT of the sentence instead
 * ("HIGH on the architecture and the build order, ..."), and splitting there
 * strands a fragment that starts mid-clause in lowercase. In that case the
 * whole line stays together and the tag is derived without consuming it. */
const CONF = /^\s*(HIGH|MEDIUM|LOW)\b\s*(?:[-—:.]+\s*|,\s+)(.+)$/i;
/** Any line that merely OPENS with a rating, used when CONF does not split. */
