  // escapes what a chat page showed literally, and "\/", "\:", "\=" ... showed
  // their backslash when only a few were listed here (2026-11-09).
  "\\\\(?<esc>[!\"#$%&'()*+,\\-./:;<=>?@\\[\\\\\\]^_`{|}~])",       // \* -> *
  "(?<tick>`+)(?<code>[\\s\\S]+?)\\k<tick>",                         // code
  "<!--[\\s\\S]*?-->",                                               // comment: hidden
  "<br\\s*\\/?>",                                                    // <br>
  // A short allowlist of inline HTML, rebuilt as fresh elements -- never
  // parsed as markup, so no attribute, handler or script can come along.
  "<(?<tag>kbd|sub|sup|mark|u|ins|del|s|b|i|strong|em|small|abbr|code|q|cite|var|samp)(?<attrs>\\s[^<>]*)?>(?<tin>[\\s\\S]*?)<\\/\\k<tag>\\s*>",
  "&(?<ent>[a-zA-Z]{2,8}|#\\d{1,6}|#x[0-9a-fA-F]{1,6});",           // &copy; &#169;
  "\\$\\$(?<mathd>[^$]+?)\\$\\$",                                   // $$display$$
  "\\\\\\[(?<mathb>[\\s\\S]+?)\\\\\\]",                             // \[display\]
  "\\\\\\((?<mathp>[\\s\\S]+?)\\\\\\)",                             // \(inline\)
  // $inline$. Not "$5 and $10": the opening $ must be followed by something
