  "(?<![\\\\$\\w])\\$(?=[^\\s$\\d])(?<math>[^$\\n]*?[^\\s$\\\\])\\$(?![\\w$])",
  "\\[\\^(?<fn>[^\\]\\s]+)\\]",                                     // [^1]
  "\\*\\*\\*(?=\\S)(?<bi>[\\s\\S]*?\\S)\\*\\*\\*",                   // bold italic
  "\\*\\*(?=\\S)(?<b>[\\s\\S]*?\\S)\\*\\*",                         // bold
