  reg: "\u00ae", trade: "\u2122", mdash: "\u2014", ndash: "\u2013", hellip: "\u2026",
  laquo: "\u00ab", raquo: "\u00bb", ldquo: "\u201c", rdquo: "\u201d", lsquo: "\u2018",
  rsquo: "\u2019", bull: "\u2022", middot: "\u00b7", deg: "\u00b0", plusmn: "\u00b1",
  times: "\u00d7", divide: "\u00f7", rarr: "\u2192", larr: "\u2190", uarr: "\u2191",
  darr: "\u2193", harr: "\u2194", check: "\u2713", euro: "\u20ac", pound: "\u00a3",
  yen: "\u00a5", cent: "\u00a2", sect: "\u00a7", para: "\u00b6", le: "\u2264", ge: "\u2265",
  ne: "\u2260", infin: "\u221e", asymp: "\u2248", micro: "\u00b5", frac12: "\u00bd",
  frac14: "\u00bc", frac34: "\u00be", sup2: "\u00b2", sup3: "\u00b3", ensp: "\u2002",
  emsp: "\u2003", thinsp: "\u2009", zwj: "\u200d", zwnj: "\u200c",
