/* ── math ─────────────────────────────────────────────────────────────────
 *  TeX is typeset with KaTeX, fetched the first time an answer contains any
 *  math and never otherwise. Until it arrives -- or if it cannot -- the TeX
 *  itself is shown in the code face, which is readable, rather than the
 *  flattened glyph soup ("∫0∞e−xdx=1") the answer used to arrive as. */
const KATEX = "https://cdn.jsdelivr.net/npm/katex@0.16.11/dist/";
let katexReady = null;
function loadKatex() {
  if (window.katex) return Promise.resolve(window.katex);
  if (katexReady) return katexReady;
  katexReady = new Promise((resolve, reject) => {
    const css = document.createElement("link");
    css.rel = "stylesheet"; css.href = KATEX + "katex.min.css";
    document.head.append(css);
    const js = document.createElement("script");
    js.src = KATEX + "katex.min.js";
    js.onload = () => resolve(window.katex);
    js.onerror = () => { katexReady = null; reject(new Error("katex")); };
    document.head.append(js);
  });
  return katexReady;
}

function mathEl(tex, display) {
  const n = el(display ? "div" : "span", display ? "md-math md-math-block" : "md-math", tex.trim());
  loadKatex().then((k) => {
    try {
      k.render(tex.trim(), n, { displayMode: display, throwOnError: false, output: "htmlAndMathml" });
      n.classList.add("typeset");
    } catch {}
  }).catch(() => {});
  return n;
}


/* Block markdown -> a small AST.
 *
 *  What it replaced swallowed fenced code (the fence lines were dropped and the
 *  code rendered as prose), rendered every heading level identically, capped
 *  lists at two levels, and had no blockquotes, rules or task lists. Models
 *  use all of those in ordinary answers, so the gaps showed up as literal
 *  markup or as a report with no visible structure.
 */
const MD = {
  fence: /^(\s*)(`{3,}|~{3,})\s*([\w+#.-]*)\s*$/,
  heading: /^\s{0,3}(#{1,6})\s+(.+?)\s*#*\s*$/,
  hr: /^\s{0,3}([-*_])(\s*\1){2,}\s*$/,
  quote: /^\s{0,3}>\s?(.*)$/,
  bullet: /^(\s*)([-*+•])\s+(.*)$/,
  ordered: /^(\s*)(\d{1,9})([.)])\s+(.*)$/,
  task: /^\[([ xX])\]\s+(.*)$/,
  math: /^\s*(\$\$|\\\[)\s*$/,
  mathLine: /^\s*(?:\$\$([\s\S]+)\$\$|\\\[([\s\S]+)\\\])\s*$/,
  footdef: /^\s{0,3}\[\^([^\]\s]+)\]:\s*(.*)$/,
  details: /^\s{0,3}<details(\s[^>]*)?>/i,
  // A line that is nothing but a wrapper tag or a comment: it shapes HTML
  // layout, which a rendered answer does not have, so it is dropped and what
  // it wraps is rendered as usual.
  htmlShell: /^\s{0,3}(?:<\/?(?:div|p|span|center|section|article|header|footer|main|aside|figure|figcaption)(?:\s[^>]*)?>\s*)+$|^\s{0,3}<!--[\s\S]*?-->\s*$/i,
};

/* A code block with no language whose first line IS a language name was
 *  captured with the page's label inside it ("Python" above the code).
 *  Answers saved before the engine learned to separate the two are repaired
 *  here, rather than showing the label as a line of code. */
const CODE_LANGS = new Set(("python py javascript js typescript ts jsx tsx json html css scss " +
  "bash sh shell zsh powershell ps1 sql java kotlin swift go golang rust c cpp c++ csharp c# " +
  "ruby php r matlab yaml yml toml xml markdown md plaintext text lua perl scala dart haskell").split(" "));

/* "\*\*Label:\*\*" is bold the chat site failed to render, escaped by the
 *  engine as if the model meant the asterisks (DeepSeek, tripped by the $ in
 *  "**Oil above $100:**", 2026-10-14). The engine no longer escapes a pair;
 *  answers saved before that are repaired here. Code blocks are left alone. */
const ESC_BOLD = /\\\*\\\*(?=[^\s*\\])([^*\n]{0,200}?[^\s*\\])\\\*\\\*/g;
/* "\1. Iran ..." is a numbered line the engine marked as not-a-list with the
 *  backslash before the DIGIT, which no markdown reads as an escape, so the
 *  backslash showed (2026-11-09). The engine now writes "1\. "; answers saved
 *  before that are repaired to the same here. */
const ESC_NUM = /^(\s*)\\(\d{1,9})([.)])(?=\s)/;
function unescapeBold(lines) {
  let fence = false;
  return lines.map((l) => {
    if (MD.fence.test(l)) { fence = !fence; return l; }
    return fence ? l : l.replace(ESC_BOLD, "**$1**").replace(ESC_NUM, "$1$2\\$3");
  });
}

function mdParse(text) {
  const lines = unescapeBold(String(text || "").replace(/\r\n?/g, "\n").replace(/\t/g, "    ").split("\n"));
  const out = [];
  const notes = [];
  let i = 0;

  const isTableRow = (l) => TABLE_ROW.test(l) || (/\|/.test(l) && /\S/.test(l.replace(/\|/g, "")) && l.split("|").length > 2);
  const startsBlock = (l, next) =>
    MD.fence.test(l) || MD.heading.test(l) || MD.quote.test(l) ||
    MD.math.test(l) || MD.mathLine.test(l) || MD.footdef.test(l) ||
    MD.details.test(l) || MD.htmlShell.test(l) ||
    MD.bullet.test(l) || MD.ordered.test(l) || MD.hr.test(l) ||
    (isTableRow(l) && next !== undefined && TABLE_SEP.test(next));

  while (i < lines.length) {
    const line = lines[i];
    if (!line.trim()) { i++; continue; }

    // ── fenced code: kept verbatim, language remembered ─────────────────────
    const f = line.match(MD.fence);
    if (f) {
      const fence = f[2], body = [];
      i++;
      while (i < lines.length && !new RegExp(`^\\s*${fence[0]}{${fence.length},}\\s*$`).test(lines[i])) {
        body.push(lines[i]); i++;
      }
      i++;                               // the closing fence, if there was one
      let lang = f[3] || "";
      if (!lang && body.length > 1 && CODE_LANGS.has(body[0].trim().toLowerCase())) {
        lang = body.shift().trim().toLowerCase();
      }
      out.push({ kind: "code", lang, text: body.join("\n") });
      continue;
    }

    // ── display math: $$ ... $$ or \[ ... \], on its own lines or one ──────
    const ml = line.match(MD.mathLine);
    if (ml) { out.push({ kind: "math", tex: ml[1] !== undefined ? ml[1] : ml[2] }); i++; continue; }
    const mo = line.match(MD.math);
    if (mo) {
      const close = mo[1] === "$$" ? /^\s*\$\$\s*$/ : /^\s*\\\]\s*$/;
      const body = [];
      i++;
      while (i < lines.length && !close.test(lines[i])) { body.push(lines[i]); i++; }
      i++;
      out.push({ kind: "math", tex: body.join("\n") });
      continue;
    }

    if (MD.htmlShell.test(line)) { i++; continue; }

    // ── <details>: a collapsible section, its body markdown in its own right ─
    if (MD.details.test(line)) {
      const open = /\bopen\b/i.test((line.match(MD.details) || [])[1] || "");
      const buf = [];
      let depth = 0;
      while (i < lines.length) {
        const l = lines[i];
        depth += (l.match(/<details(\s[^>]*)?>/gi) || []).length;
        depth -= (l.match(/<\/details\s*>/gi) || []).length;
        buf.push(l);
        i++;
        if (depth <= 0) break;
      }
      let body = buf.join("\n")
        .replace(/^\s*<details(\s[^>]*)?>/i, "")
        .replace(/<\/details\s*>\s*$/i, "");
      let summary = "Details";
      const sm = body.match(/<summary(?:\s[^>]*)?>([\s\S]*?)<\/summary\s*>/i);
      if (sm) { summary = sm[1].trim() || summary; body = body.replace(sm[0], ""); }
      out.push({ kind: "details", open, summary, blocks: mdParse(body) });
      continue;
    }

    // ── footnote definitions: gathered, and listed at the end ───────────────
    const fd = line.match(MD.footdef);
    if (fd) {
      const text = [fd[2]];
      i++;
      while (i < lines.length && /^\s{2,}\S/.test(lines[i])) { text.push(lines[i].trim()); i++; }
      notes.push({ id: fd[1], text: text.join(" ") });
      continue;
    }

    const h = line.match(MD.heading);
    if (h) { out.push({ kind: "h", level: h[1].length, text: h[2] }); i++; continue; }

    // ── table: a header row with a separator under it ───────────────────────
    if (isTableRow(line) && i + 1 < lines.length && TABLE_SEP.test(lines[i + 1])) {
      const head = cells(line);
      const align = cells(lines[i + 1]).map((c) =>
        /^:-+:$/.test(c) ? "center" : /^-+:$/.test(c) ? "right" : /^:-+$/.test(c) ? "left" : "");
      const rows = [];
      i += 2;
      while (i < lines.length && lines[i].trim() && isTableRow(lines[i])) {
        rows.push(cells(lines[i])); i++;
      }
      out.push({ kind: "table", head, align, rows });
      continue;
    }

    if (MD.hr.test(line)) { out.push({ kind: "hr" }); i++; continue; }

    // ── blockquote: its own content is markdown too ─────────────────────────
    if (MD.quote.test(line)) {
      const inner = [];
      while (i < lines.length && (MD.quote.test(lines[i]) || (lines[i].trim() && inner.length && !startsBlock(lines[i], lines[i + 1])))) {
        const q = lines[i].match(MD.quote);
        inner.push(q ? q[1] : lines[i]);
        i++;
      }
      out.push({ kind: "quote", blocks: mdParse(inner.join("\n")) });
      continue;
    }

    // ── lists, nested to any depth by indentation ───────────────────────────
    if (MD.bullet.test(line) || MD.ordered.test(line)) {
      const { list, next } = parseList(lines, i);
      out.push({ kind: "list", list });
      i = next;
      continue;
    }

    // ── paragraph: until a blank line or the start of another block ─────────
    const para = [];
    while (i < lines.length && lines[i].trim() && !startsBlock(lines[i], lines[i + 1])) {
      para.push(lines[i].trim());
      i++;
    }
    out.push({ kind: "p", lines: para, text: para.join(" ") });
  }
  if (notes.length) out.push({ kind: "footnotes", notes });
  return out;
}

/* A list from `start`, with nested lists wherever indentation grows.
 *
 *  A blank line inside a list does NOT end it -- models put blank lines
 *  between bullets all the time -- unless what follows is not a list item and
 *  not indented continuation.
 */
function parseList(lines, start) {
  const itemOf = (l) => {
    const b = l.match(MD.bullet);
    if (b) return { indent: b[1].length, ordered: false, body: b[3], num: null };
    const o = l.match(MD.ordered);
    if (o) return { indent: o[1].length, ordered: true, body: o[4], num: +o[2] };
    return null;
  };
  const first = itemOf(lines[start]);
  const list = { ordered: first.ordered, start: first.num || 1, items: [] };
  const base = first.indent;
  let i = start;

  while (i < lines.length) {
    const l = lines[i];
    if (!l.trim()) {
      // Look past blank lines: still this list only if an item follows.
      let k = i + 1;
      while (k < lines.length && !lines[k].trim()) k++;
      const nx = k < lines.length ? itemOf(lines[k]) : null;
      if (!nx || nx.indent < base) break;
      i = k;
      continue;
    }
    const it = itemOf(l);
    if (it && it.indent === base) {
      if (it.ordered !== list.ordered && list.items.length) break;
      const t = it.body.match(MD.task);
      list.items.push({
        text: t ? t[2] : it.body,
        task: t ? t[1].toLowerCase() === "x" : null,
        children: [],
        extra: [],
      });
      i++;
      continue;
    }
    if (it && it.indent > base && list.items.length) {
      const sub = parseList(lines, i);
      list.items[list.items.length - 1].children.push(sub.list);
      i = sub.next;
      continue;
    }
    if (it && it.indent < base) break;
    // Indented continuation of the previous item's text.
    if (!it && list.items.length && /^\s{2,}\S/.test(l)) {
      list.items[list.items.length - 1].extra.push(l.trim());
      i++;
      continue;
    }
    break;
  }
  return { list, next: i };
}

/* The verdict: its ANSWER / NOTES / CONFIDENCE sections, each parsed as
 * markdown in its own right.
 *
 *  The section split is the only thing verdict-specific here. It used to be
 *  tangled into a line-by-line parser that had to reimplement every block
 *  type for itself, which is how the gaps above appeared.
 */
function parseVerdict(text) {
  const g = { main: [], notes: [], conf: [] };
  const buckets = { main: [], notes: [], conf: [] };
  let where = "main";
  let fenced = false;

  // A capture that lost the newline after a section label leaves it glued to
  // the text it heads ("ANSWER AI consumes...", "CONFIDENCE HIGH -- ...").
  // Only the exact UPPERCASE labels are split off, so prose that merely
  // starts with "Notes on..." is left alone.
  // One that lost the breaks on BOTH sides glues the label to the end of the
  // previous sentence too ("...*Dream*.NOTES None.CONFIDENCE HIGH", a sole
  // Gemini verdict, 2026-09-30): only right after a sentence's end, and only
  // followed by a space or a colon, so "NOTES-style" in prose stays put.
  const unglued = String(text || "").replace(/\r/g, "")
    .replace(/([.!?][*_"')\]]*)[ \t]*(NOTES|CONFIDENCE)(?=[ \t]*:|[ \t]+\S)/g, "$1\n$2");
  const lines = unglued.split("\n").flatMap((l) => {
    const m = l.match(/^\s*(?:#{1,4}\s*)?(ANSWER|NOTES|CONFIDENCE|CAVEATS)(?:\s*:\s*|\s+)(?=\S)(.+)$/);
    return m ? [m[1], m[2]] : [l];
  });
  for (const raw of lines) {
    if (MD.fence.test(raw)) fenced = !fenced;
    const sec = !fenced && raw.match(SECTION);
    if (sec) {
      const s = sec[1].toUpperCase();
      where = s === "NOTES" || s === "CAVEATS" ? "notes" : s === "CONFIDENCE" ? "conf" : "main";
      // Verdicts archived under the older prompt open with AGREEMENTS and
      // DISAGREEMENTS before the answer; label them rather than letting the
      // deliberation notes masquerade as the answer's opening paragraph.
      if (s === "AGREEMENTS" || s === "DISAGREEMENTS" || s === "VERDICT") {
        buckets.main.push("", `### ${s[0] + s.slice(1).toLowerCase()}`, "");
      }
      continue;
    }
    buckets[where].push(raw);
  }

  // A line that is only **bold** stays bold text. It used to be promoted to a
  // sub-heading, which is how "**Bold text**" in a markdown demo rendered as
  // a "BOLD TEXT" section label; a model that wants a heading writes one.
  g.main = mdParse(buckets.main.join("\n"));
  g.notes = mdParse(buckets.notes.join("\n"));

  // Confidence: a HIGH/MEDIUM/LOW opener is a rating wherever it appears --
  // some chairmen drop the heading and just write the line.
  const pull = (list) => list.filter((b) => {
    if (b.kind !== "p") return true;
    const lead = b.text.match(CONF_LEAD);
    if (!lead) return true;
    const c = b.text.match(CONF);
    g.conf.push({ kind: "conf", level: lead[1].toUpperCase(), why: c ? c[2].trim() : b.text });
    return false;
  });
  g.main = pull(g.main);
  g.notes = pull(g.notes);
  for (const b of mdParse(buckets.conf.join("\n"))) {
    if (b.kind === "p") {
      const lead = b.text.match(CONF_LEAD);
      if (lead) {
        const c = b.text.match(CONF);
        g.conf.push({ kind: "conf", level: lead[1].toUpperCase(), why: c ? c[2].trim() : b.text });
        continue;
      }
    }
    g.conf.push(b);
  }

  // A sidebar card reading only "None." is noise.
  if (g.notes.length === 1 && g.notes[0].kind === "p" && /^none[.!]?$/i.test(g.notes[0].text))
    g.notes = [];
  return g;
}

function renderList(list) {
  const n = el(list.ordered ? "ol" : "ul", "v-list");
  if (list.ordered && list.start && list.start !== 1) n.start = list.start;
  for (const it of list.items) {
    const li = el("li");
    if (it.task !== null && it.task !== undefined) {
      li.classList.add("md-task");
      const box = el("span", `md-check ${it.task ? "on" : ""}`, it.task ? "\u2713" : "");
      box.setAttribute("aria-hidden", "true");
      li.append(box);
    }
    inline(li, it.text);
    for (const x of it.extra || []) { li.append(el("br")); inline(li, x); }
    for (const child of it.children || []) li.append(renderList(child));
    n.append(li);
  }
  return n;
}

/** Paragraph lines keep their breaks: a model that put two things on two
 *  lines meant them apart, and joining them into one run-on reads wrong. */
function renderPara(host, lines) {
  lines.forEach((l, k) => {
    if (k) host.append(el("br"));
    inline(host, l);
  });
  return host;
}

function renderBlocks(host, blocks, lead = false) {
  blocks.forEach((b, i) => {
    if (b.kind === "h") {
      const lvl = Math.min(6, Math.max(1, b.level || 3));
      host.append(inline(el("div", `v-h md-h md-h${lvl}`), b.text));
      return;
    }
    if (b.kind === "list") { host.append(renderList(b.list)); return; }
    if (b.kind === "hr") { host.append(el("hr", "md-hr")); return; }
    if (b.kind === "math") { host.append(mathEl(b.tex, true)); return; }
    if (b.kind === "details") {
      const d = el("details", "md-details");
      if (b.open) d.open = true;
      d.append(inline(el("summary", "md-summary"), b.summary));
      d.append(renderBlocks(el("div", "md-details-body"), b.blocks));
      host.append(d);
      return;
    }
    if (b.kind === "footnotes") {
      const box = el("div", "md-footnotes");
      const ol = el("ol");
      for (const n of b.notes) {
        const li = el("li");
        li.append(el("span", "md-fn-id", n.id));
        inline(li, n.text);
        ol.append(li);
      }
      box.append(ol);
      host.append(box);
      return;
    }
    if (b.kind === "quote") {
      host.append(renderBlocks(el("blockquote", "md-quote"), b.blocks));
      return;
    }
    if (b.kind === "code") {
      const wrap = el("div", "md-pre-wrap");
      // A header on EVERY block, language or not, because it carries the copy
      // button: a command an agent hands you ("run this in PowerShell") is
      // meant to be pasted, and selecting a line that scrolls off sideways
      // by hand is how half of one gets copied.
      const hd = el("div", "md-pre-hd");
      hd.append(el("span", "md-pre-lang", b.lang || "code"));
      const code = b.text;
      hd.append(copyButton(() => ({ md: code }), { cls: "md-pre-copy", plain: true }));
      wrap.append(hd);
      const pre = el("pre", "md-pre");
      pre.append(el("code", null, b.text));
      wrap.append(pre);
      attachScrollbar(pre);
      host.append(wrap);
      return;
    }
    if (b.kind === "conf") {
      const p = el("p", "v-conf");
      p.append(el("span", `conf-tag ${b.level.toLowerCase()}`, b.level));
      if (b.why) {
        const why = el("span", "conf-why");
        const echo = b.why.match(new RegExp(`^(${b.level})\\b`, "i"));
        if (echo) why.append(el("span", "conf-echo", echo[1]));
        inline(why, echo ? b.why.slice(echo[1].length) : b.why);
        p.append(why);
      }
      host.append(p);
      return;
    }
    if (b.kind === "table") {
      const wrap = el("div", "v-tablewrap"), t = el("table", "v-table");
      const cols = Math.max(b.head ? b.head.length : 0, ...b.rows.map((r) => r.length));
      const cell = (tag, text, k) => {
        const c = inline(el(tag), text || "");
        const a = b.align && b.align[k];
        if (a) c.style.textAlign = a;
        return c;
      };
      if (b.head) {
        const tr = el("tr");
        for (let k = 0; k < cols; k++) tr.append(cell("th", b.head[k], k));
        const thead = el("thead");
        thead.append(tr);
        t.append(thead);
      }
      const tb = el("tbody");
      for (const r of b.rows) {
        const tr = el("tr");
        // Short rows are padded, so a ragged table keeps its grid.
        for (let k = 0; k < cols; k++) tr.append(cell("td", r[k], k));
        tb.append(tr);
      }
      t.append(tb);
      wrap.append(t);
      attachScrollbar(wrap);
      host.append(wrap);
      return;
    }
    // Lead styling marks the answer's opening line, only when the answer
    // actually opens with a paragraph.
    const p = el("p", lead && i === 0 ? "v-lead" : null);
    host.append(renderPara(p, b.lines || [b.text]));
  });
  return host;
}

/** Any unit's answer, rendered as markdown rather than as a wall of symbols. */
function mdBody(text) {
  return renderBlocks(el("div", "md"), mdParse(text));
}

/** The verdict body: answer on the left, notes and confidence in a sidebar on
 *  wide screens. The sidebar is omitted entirely when there is nothing to put
 *  in it, so a plain-prose verdict just reads as one column. */
function verdictBody(text) {
  const g = parseVerdict(text);
  const hasAside = g.notes.length > 0 || g.conf.length > 0;
  const root = el("div", `verdict-body ${hasAside ? "split" : ""}`);
  root.append(renderBlocks(el("div", "v-main"), g.main, true));
  if (hasAside) {
    const aside = el("aside", "v-aside");
    if (g.notes.length) {
      const c = el("div", "v-card");
      c.append(el("div", "sec", "Notes"));
      renderBlocks(c, g.notes);
      aside.append(c);
    }
    if (g.conf.length) {
      const c = el("div", "v-card");
      c.append(el("div", "sec", "Confidence"));
      renderBlocks(c, g.conf);
      aside.append(c);
    }
    root.append(aside);
  }
  return root;
}

/* ══ the brief: a verdict laid out as a briefing ═══════════════════════════
   The same text as verdictBody, drawn the way TradeHub's Market Summary is:
   a headline and summary up top with a confidence meter, then each section as
   its own card, bold-led bullets as key-point cards, notes as a "worth
   knowing" panel. Everything comes from structure the chairman ALREADY
   writes (ANSWER / NOTES / CONFIDENCE, ### sections, **bold** lead phrases),
   so it costs no extra prompt, no engine change and no time -- and every past
   deliberation gets it too. A verdict with no structure to find simply reads
   as a hero plus prose, never worse than the text view. */

const VERDICT_VIEW = {
  get: () => { try { return localStorage.getItem("magi.verdict.view") === "text" ? "text" : "brief"; } catch { return "brief"; } },
  set: (v) => { try { localStorage.setItem("magi.verdict.view", v); } catch {} },
};

/** "**Label:** rest" / "**Label** — rest" -> { label, rest }; null otherwise. */
function boldLead(text) {
  const m = String(text || "").match(/^\s*(?:\*\*|__)(.{2,90}?)(?:\*\*|__)\s*([:：—–-]\s*)?([\s\S]*)$/);
  if (!m) return null;
  const rest = m[3].trim();
  // "**Label:** text" is a label over its body. "**Oil climbs above $100**,
  // particularly if..." is one sentence that happens to open in bold --
  // splitting it left a card body starting ", particularly".
  const labelled = !!m[2] || /[:：]\s*$/.test(m[1]) || !rest;
  return { label: m[1].replace(/[:：]\s*$/, "").trim(), rest, joined: !labelled && /^[,;.)\]a-z]/.test(rest) };
}

/** A list, as cards when it is a list of labelled points, as numbered steps
 *  when it is ordered, and as a plain list otherwise. */
function briefList(list) {
  const items = list.items;
  const leads = items.map((it) => boldLead(it.text));
  const labelled = leads.filter(Boolean).length;
  if (items.length >= 2 && labelled / items.length >= 0.6) {
    const short = items.every((it) => (it.text.length + (it.extra || []).join(" ").length) < 260 && !(it.children || []).length);
    const grid = el("div", `br-points ${short && items.length > 1 ? "two" : ""}`);
    items.forEach((it, k) => {
      const card = el("div", "br-point");
      const lead = leads[k];
      // A numbered list is a ranking; turned into cards it keeps its numbers.
      let host = card;
      if (list.ordered) {
        card.classList.add("numbered");
        card.append(el("span", "br-point-n", String((list.start || 1) + k)));
        host = el("div", "br-point-main");
        card.append(host);
      }
      const split = lead && !lead.joined;
      if (split) host.append(inline(el("div", "br-point-label"), lead.label));
      const body = el("div", `br-point-body ${lead && lead.joined ? "joined" : ""}`);
      const rest = split ? lead.rest : it.text;
      if (rest) inline(body, rest);
      for (const x of it.extra || []) { body.append(el("br")); inline(body, x); }
      if (rest || (it.extra || []).length) host.append(body);
      for (const c of it.children || []) host.append(renderList(c));
      grid.append(card);
    });
    return grid;
  }
  if (list.ordered && items.length >= 2) {
    const steps = el("ol", "br-steps");
    items.forEach((it, k) => {
      const li = el("li", "br-step");
      li.append(el("span", "br-step-n", String((list.start || 1) + k)));
      const body = el("div", "br-step-body");
      const lead = leads[k];
      if (lead) {
        body.append(inline(el("div", "br-step-label"), lead.label));
        if (lead.rest) body.append(inline(el("div"), lead.rest));
      } else inline(body, it.text);
      for (const x of it.extra || []) { body.append(el("br")); inline(body, x); }
      for (const c of it.children || []) body.append(renderList(c));
      li.append(body);
      steps.append(li);
    });
    return steps;
  }
  return renderList(list);
}

/* What a model writes, recognised as more than prose. Every unit reaches for
   the same handful of devices -- a bold label on its own line over a list
   ("**Bullish if:**"), a bold run of tickers, "**Important:**" asides,
   "A ↑ → B ↑ → C ↓" chains -- so recognising them is what lets an answer from
   ANY unit, or any chairman, render as a briefing rather than a wall. */
const TONE_BAD = /\b(bear(ish)?|downside|cons|disadvantages?|drawbacks?|risks?|weakness(es)?|threats?|headwinds?|negatives?|worst[- ]case|avoid|warnings?|pitfalls?|red flags?|dangers?|concerns?)\b/i;
const TONE_GOOD = /\b(bull(ish)?|upside|pros|advantages?|benefits?|strengths?|opportunit(y|ies)|tailwinds?|positives?|best[- ]case|catalysts?|wins?)\b/i;
const toneOf = (label) => (TONE_BAD.test(label) ? "bad" : TONE_GOOD.test(label) ? "good" : "");

const LABEL_ONLY = /^\s*(?:\*\*|__)([^*_\n]{1,48}?)\s*[:：]?\s*(?:\*\*|__)\s*[:：]?\s*$/;
const PLAIN_LABEL = /^\s*([A-Z][^.!?\n*]{0,32}?)\s*:\s*$/;
const CALLOUT = /^\s*(?:\*\*|__)\s*((?:important|note|notes|warning|caution|correction|caveat|heads[- ]up|tip|reminder|disclaimer|key (?:point|takeaway|insight))\b[^*_\n]{0,40}?)\s*[:：]?\s*(?:\*\*|__)\s*[:：]?\s*([\s\S]+)$/i;

/** "**A, B, C, D**, plus the rest" -> chips A B C D and a note. Loose mode
 *  (under a label like "Most affected:") also takes an unbolded list. */
function briefChips(text, loose) {
  const t = String(text || "").trim();
  let cand = null, note = "";
  const m = t.match(/^\*\*([^*]+)\*\*\s*[,;:.]?\s*([\s\S]*)$/);
  if (m) { cand = m[1]; note = m[2]; }
  else if (loose) cand = t.replace(/\*\*/g, "");
  if (!cand) return null;
  const items = cand.split(/\s*[,;]\s*/).map((s) => s.trim().replace(/\.$/, "")).filter(Boolean);
  if (items.length < 3 || !items.every((s) => s.length <= 30)) return null;
  const wrap = el("div", "br-chipset");
  const chips = el("div", "br-chips");
  items.forEach((s) => chips.append(inline(el("span", "br-chip"), s)));
  wrap.append(chips);
  note = note.replace(/^(?:and|plus)\s+/i, "").trim();
  if (note) wrap.append(inline(el("div", "br-chip-note"), note.charAt(0).toUpperCase() + note.slice(1)));
  return wrap;
}

/** "Oil ↑ → yields ↑ → Nasdaq ↓" as a row of steps. */
function briefFlow(text) {
  const t = String(text || "").trim().replace(/^\*\*|\*\*$/g, "");
  if ((t.match(/→|->|⟶|⇒/g) || []).length < 2) return null;
  const steps = t.split(/\s*(?:→|->|⟶|⇒)\s*/);
  if (steps.some((s) => !s.trim() || s.length > 48)) return null;
  const row = el("div", "br-flow");
  steps.forEach((s, k) => {
    if (k) row.append(el("span", "br-flow-arrow", "→"));
    const dir = /↑|⬆/.test(s) ? "up" : /↓|⬇/.test(s) ? "down" : "";
    row.append(inline(el("span", `br-flow-step ${dir}`), s.replace(/\*\*/g, "").trim()));
  });
  return row;
}

function briefBlocks(host, blocks) {
  let groups = null;             // the grid a run of labelled groups shares
  for (let i = 0; i < blocks.length; i++) {
    const b = blocks[i];
    if (b.kind === "hr") continue;                  // cards already separate
    if (b.kind === "h") {
      groups = null;
      host.append(inline(el("div", "br-subhd"), b.text));
      continue;
    }
    if (b.kind === "p") {
      const next = blocks[i + 1];
      const lab = b.text.match(LABEL_ONLY) || (b.text.length <= 36 ? b.text.match(PLAIN_LABEL) : null);
      if (lab && next && (next.kind === "list" || next.kind === "p" || next.kind === "table")) {
        const label = lab[1].trim();
        const box = el("div", `br-group ${toneOf(label)}`);
        const hd = el("div", "br-group-hd");
        hd.append(el("span", "br-group-dot"), inline(el("span"), label));
        box.append(hd);
        let wide = false;
        if (next.kind === "list") box.append(briefList(next.list));
        else if (next.kind === "p") {
          const chips = briefChips(next.text, true);
          wide = !!chips;
          box.append(chips || inline(el("p"), next.text));
        } else { wide = true; renderBlocks(box, [next]); }
        i++;
        // A row of chips or a table spans the card on its own row, outside the
        // grid -- inside it, it held a third column open that left the
        // Bullish/Bearish pair beside it at two-thirds width.
        if (wide) { box.classList.add("wide"); host.append(box); groups = null; continue; }
        if (!groups) { groups = el("div", "br-groups"); host.append(groups); }
        groups.append(box);
        continue;
      }
      groups = null;
      const co = b.text.match(CALLOUT);
      if (co) {
        const box = el("div", `br-callout ${toneOf(co[1])}`);
        box.append(inline(el("div", "br-callout-hd"), co[1].trim()), inline(el("div", "br-callout-body"), co[2]));
        host.append(box);
        continue;
      }
      const flow = briefFlow(b.text);
      if (flow) { host.append(flow); continue; }
      const chips = briefChips(b.text, false);
      if (chips) { host.append(chips); continue; }
    }
    groups = null;
    if (b.kind === "list") host.append(briefList(b.list));
    else renderBlocks(host, [b]);
  }
  return host;
}

/** "Priority #1 — Fed Repricing" -> { n: "1", kicker: "Priority", title }.
 *  Also "1. X", "#2: X", "Step 3 - X", "Part 4) X". */
function briefNumbered(title) {
  const t = String(title || "").trim();
  let m = t.match(/^(priority|tier|step|part|phase|stage|rank|section|chapter|day|option|reason|tip)\s*#?\s*(\d{1,2})\s*[—–:.)\-]\s*(.+)$/i);
  if (m) return { n: m[2], kicker: m[1], title: m[3] };
  m = t.match(/^#?(\d{1,2})\s*(?:[.)]\s+|\s*[—–:\-]\s*)(.+)$/);
  if (m) return { n: m[1], kicker: "", title: m[2] };
  return { n: "", kicker: "", title: t };
}
const BRIEF_HIGHLIGHT = /^(bottom line|summary|in summary|conclusion|tl;?dr|key takeaways?|the verdict|final (?:take|thoughts|answer|verdict)|recommendation|what to do|action plan)\b/i;

/** Splits a lead paragraph into a headline and the rest, when its first
 *  sentence is short enough to be one. */
function splitHeadline(text) {
  const t = String(text || "").trim();
  if (t.length <= 170) return { head: t, rest: "" };
  // First sentence end: . ! ? followed by a space and a capital -- so "e.g."
  // and "U.S. data" do not end it.
  const m = t.match(/^([\s\S]{25,170}?[.!?])\s+(?=[A-Z"“(])/);
  if (m) return { head: m[1], rest: t.slice(m[0].length) };
  // One long sentence is still the headline, just set a size down.
  return t.length <= 280 ? { head: t, rest: "", long: true } : { head: "", rest: t };
}

/** opts.report: the Studio Report's document layout -- a cover naming the
 *  question, numbered chapters, and a sticky contents rail that follows the
 *  reader on wide screens (chips on narrow ones). */
function briefBody(text, opts = {}) {
  const g = parseVerdict(text);
  const report = !!opts.report;
  const root = el("div", `verdict-body brief ${report ? "report" : ""}`);
  const blocks = [...g.main];

  /* hero */
  const hero = el("div", "br-hero");
  const lead = blocks[0] && blocks[0].kind === "p" ? blocks.shift() : null;
  if (report) {
    hero.append(el("div", "br-kicker", "Report"));
    if (opts.title) hero.append(inline(el("h2", "br-cover-title"), opts.title));
    if (lead) hero.append(inline(el("div", "br-lede"), lead.text));
  } else if (lead) {
    const { head, rest, long } = splitHeadline(lead.text);
    if (head) hero.append(inline(el("div", `br-headline ${long ? "long" : ""}`), head));
    // The headline stood alone and the answer goes on with a short framing
    // paragraph before its first section: that paragraph is the summary.
    const next = blocks[0];
    const summary = rest || (next && next.kind === "p" && next.text.length <= 420 ? (blocks.shift(), next.text) : "");
    if (summary) hero.append(inline(el("div", "br-summary"), summary));
  }
  const conf = g.conf.find((b) => b.kind === "conf");
  if (conf) {
    const lv = { LOW: 1, MEDIUM: 2, HIGH: 3 }[conf.level] || 0;
    const meter = el("div", `br-conf ${conf.level.toLowerCase()}`);
    const top = el("div", "br-conf-top");
    const bar = el("div", "br-conf-bar");
    for (let k = 1; k <= 3; k++) bar.append(el("i", k <= lv ? "on" : ""));
    top.append(el("span", "br-conf-k", "Confidence"), bar, el("span", "br-conf-v", conf.level));
    meter.append(top);
    if (conf.why) {
      let why = conf.why.replace(new RegExp(`^${conf.level}\\b\\s*[-—:.,]*\\s*`, "i"), "");
      why = why.charAt(0).toUpperCase() + why.slice(1);
      if (why) meter.append(inline(el("div", "br-conf-why"), why));
    }
    hero.append(meter);
  }

  /* sections: every heading opens a card, whatever its level. Models mix #,
     ## and ### freely (ChatGPT: a ## title, ### priorities, then # parts),
     and splitting only on the shallowest level left everything under the
     others as uncarded prose. A heading with nothing under it before the next
     heading is a GROUP title; a deeper heading inside a card that already has
     content is that card's sub-heading. */
  const sections = [];
  let cur = { title: null, level: 0, blocks: [] };
  const push = () => { if (cur.title !== null || cur.blocks.length) sections.push(cur); };
  const nextReal = (i) => { let j = i + 1; while (blocks[j] && blocks[j].kind === "hr") j++; return blocks[j]; };
  blocks.forEach((b, i) => {
    if (b.kind !== "h") { cur.blocks.push(b); return; }
    const lvl = b.level || 3;
    if (cur.title !== null && lvl > cur.level && cur.blocks.some((x) => x.kind !== "hr")) {
      cur.blocks.push(b);
      return;
    }
    push();
    const nx = nextReal(i);
    if (nx && nx.kind === "h" && (nx.level || 3) >= lvl) {
      sections.push({ group: b.text });
      cur = { title: null, level: 0, blocks: [] };
      return;
    }
    cur = { title: b.text, level: lvl, blocks: [] };
  });
  push();
  const titled = sections.filter((s) => typeof s.title === "string");

  if (hero.childNodes.length) root.append(hero);

  // A report numbers its chapters even when the model did not, so the
  // contents and the cards read as one document.
  const chapter = (s, k) => {
    const c = briefNumbered(s.title);
    return { n: report ? String(k + 1) : c.n, kicker: c.kicker, title: c.title };
  };

  // contents chips when there is enough to navigate
  const secEls = [];
  const jump = (k) => secEls[k] && secEls[k].scrollIntoView({ behavior: "smooth", block: "start" });
  if (titled.length >= (report ? 2 : 3)) {
    const toc = el("div", "br-toc");
    titled.forEach((s, k) => {
      const b = el("button", "br-toc-chip");
      b.type = "button";
      inline(b, chapter(s, k).title);
      b.onclick = () => jump(k);
      toc.append(b);
    });
    root.append(toc);
  }

  // A report's body sits beside a contents rail; a verdict's is the root.
  let host = root, rail = null;
  if (report && titled.length >= 2) {
    const doc = el("div", "br-doc");
    rail = el("nav", "br-rail");
    rail.setAttribute("aria-label", "Contents");
    rail.append(el("div", "br-rail-hd", "Contents"));
    titled.forEach((s, k) => {
      const c = chapter(s, k);
      const b = el("button", "br-rail-item");
      b.type = "button";
      if (c.n) b.append(el("span", "br-rail-n", c.n.padStart(2, "0")));
      b.append(inline(el("span", "br-rail-t"), c.title));
      b.onclick = () => jump(k);
      rail.append(b);
    });
    host = el("div", "br-doc-main");
    doc.append(rail, host);
    root.append(doc);
  }

  let k = 0;
  for (const s of sections) {
    if (s.group !== undefined) {
      host.append(inline(el("div", "br-group-title"), s.group));
      continue;
    }
    if (s.title === null) {
      if (s.blocks.length) host.append(briefBlocks(el("div", "br-intro"), s.blocks));
      continue;
    }
    const c = chapter(s, k++);
    const tone = toneOf(c.title);
    const card = el("section", `br-sec ${tone ? "tone-" + tone : ""} ${BRIEF_HIGHLIGHT.test(c.title) ? "hl" : ""}`);
    const hd = el("div", "br-sec-hd");
    if (c.n) hd.append(el("span", "br-sec-n", c.n));
    const tw = el("div", "br-sec-tw");
    if (c.kicker) tw.append(el("div", "br-sec-kicker", c.kicker));
    tw.append(inline(el("h3", "br-sec-title"), c.title));
    hd.append(tw);
    card.append(hd);
    if (s.blocks.length) card.append(briefBlocks(el("div", "br-sec-body"), s.blocks));
    secEls.push(card);
    host.append(card);
  }

  // The rail marks the chapter being read.
  if (rail && "IntersectionObserver" in window) {
    const items = [...rail.querySelectorAll(".br-rail-item")];
    const io = new IntersectionObserver((entries) => {
      for (const e of entries) {
        if (!e.isIntersecting) continue;
        const i = secEls.indexOf(e.target);
        items.forEach((it, j) => it.classList.toggle("on", j === i));
      }
    }, { rootMargin: "-15% 0px -70% 0px" });
    secEls.forEach((s) => io.observe(s));
    root.stopSpy = () => io.disconnect();
  }

  /* notes + the rest of the confidence section */
  const confRest = g.conf.filter((b) => b.kind !== "conf");
  if (g.notes.length || confRest.length) {
    const notes = el("div", "br-notes");
    const hd = el("div", "br-notes-hd");
    hd.append(icSpan("br-notes-ic", "help"), el("span", null, "Worth knowing"));
    notes.append(hd);
    briefBlocks(notes, [...g.notes, ...confRest]);
    host.append(notes);
  }
  return root;
}


  /* ════════ end of magi.html ════════ */

